def parse_orders(rows):
    total = 0.0
    for row in rows:
        if "price" not in row:
            raise ValueError(f"row missing price: {row!r}")
        try:
            total += float(row["price"])
        except (TypeError, ValueError):
            raise ValueError(f"price not numeric: {row['price']!r}")
    return round(total, 2)


TESTS = [
    "test_sums_valid_orders",
    "test_empty_list_totals_zero",
    "test_row_missing_price_raises",
    "test_non_numeric_price_raises",
]


def run_tests():
    results = []

    def record(name, passed):
        results.append(("PASS " if passed else "FAIL ") + name)

    record(TESTS[0], parse_orders([{"price": "20.00"}, {"price": "25.50"}]) == 45.50)
    record(TESTS[1], parse_orders([]) == 0.0)

    try:
        parse_orders([{"sku": "A1"}])
        record(TESTS[2], False)
    except ValueError:
        record(TESTS[2], True)

    try:
        parse_orders([{"price": "free"}])
        record(TESTS[3], False)
    except ValueError:
        record(TESTS[3], True)

    return results


results = run_tests()
for line in results:
    print(line)
passed = sum(1 for r in results if r.startswith("PASS"))
print(f"{passed} passed")

