def binary_search(items, target):
    low, high = 0, len(items) - 1
    while low <= high:
        middle = (low + high) // 2
        if items[middle] == target:
            return middle
        if items[middle] < target:
            low = middle + 1
        else:
            high = middle - 1
    return -1

data = [2, 5, 8, 12, 16, 23, 38, 45, 56, 72, 91]
for target in [23, 2, 91, 16, 7, 100]:
    print(f"{target} -> {binary_search(data, target)}")

